#!/usr/bin/env python3
import sys
import re

def view_class(filename, classname):
    with open(filename, 'r') as f:
        lines = f.readlines()

    in_class = False
    class_lines = []

    for i, line in enumerate(lines):
        if re.match(f'^class {classname}', line):
            in_class = True
            class_lines.append((i+1, line))
        elif in_class:
            if line.strip() and not line.startswith(' ') and not line.startswith('\t'):
                break
            if re.match(r'^class [A-Z]', line):
                break
            class_lines.append((i+1, line))

    if class_lines:
        for line_num, line in class_lines:
            print(f"{line_num:4d}: {line}", end='')
    else:
        print(f"Class {classname} not found")

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: view_class.py <filename> <classname>")
        sys.exit(1)
    view_class(sys.argv[1], sys.argv[2])
